// Shannon effective ionic and crystal radii, with a lookup that never substitutes a value.
// @source S-001 (R. D. Shannon, Acta Cryst. A32, 751, 1976) via S-034 (pymatgen's bundled table).
// Data: src/data/shannon-radii.json, generated by scripts/data/build_shannon.py. Licence and completeness: Q-002.
import data from '../../data/shannon-radii.json';

export type Geometry = 'SQ' | 'PY';
export type Spin = 'HS' | 'LS';
export interface ShannonEntry {
  el: string;
  /** null only for the entries listed in `shannonMeta.anomalies` (oxidation state missing upstream). */
  ox: number | null;
  cn: number;
  geometry: Geometry | null;
  spin: Spin | null;
  /** Effective ionic radius, angstrom. */
  ionic: number;
  /** Crystal radius, angstrom. */
  crystal: number;
}
export type RadiusKind = 'ionic' | 'crystal';
export interface RadiusQuery {
  el: string;
  ox: number;
  cn: number;
  spin?: Spin;
  /** Omit (or null) for the plain coordination entry; 'SQ' square planar, 'PY' pyramidal. */
  geometry?: Geometry | null;
  kind: RadiusKind;
}
export type LookupReason = 'unknown element' | 'no entry' | 'geometry required' | 'spin required';
export type RadiusResult =
  | { ok: true; value: number; entry: ShannonEntry; note?: string }
  | { ok: false; reason: LookupReason; message: string; available: ShannonEntry[] };

export const SHANNON_ENTRIES = data.entries as ShannonEntry[];
export const shannonMeta = data._meta;

const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII', 'XIII', 'XIV'];

/** Shannon's coordination label, for example `VI`, `IVSQ`, `IIIPY`. */
export function coordinationLabel(cn: number, geometry: Geometry | null = null): string {
  return (ROMAN[cn] ?? String(cn)) + (geometry ?? '');
}

/** Ion label such as `Fe3+`, `O2-`, `Na+`. */
export function ionLabel(el: string, ox: number): string {
  const mag = Math.abs(ox);
  return `${el}${mag === 1 ? '' : mag}${ox < 0 ? '-' : '+'}`;
}

const GEOM_NAME: Record<Geometry, string> = { SQ: 'square planar', PY: 'pyramidal' };
const describe = (e: ShannonEntry) => `${coordinationLabel(e.cn, e.geometry)}${e.spin ? ` ${e.spin}` : ''}`;

const byElement = (el: string) => SHANNON_ENTRIES.filter((e) => e.el === el);

/** Oxidation states the table lists for an element, ascending. */
export function oxidationStates(el: string): number[] {
  const set = new Set<number>();
  for (const e of byElement(el)) if (e.ox !== null) set.add(e.ox);
  return [...set].sort((a, b) => a - b);
}

/** Coordinations listed for an ion, in table order (CN ascending, plain before SQ before PY). */
export function coordinations(el: string, ox: number): { cn: number; geometry: Geometry | null }[] {
  const out: { cn: number; geometry: Geometry | null }[] = [];
  for (const e of byElement(el)) {
    if (e.ox !== ox) continue;
    if (!out.some((c) => c.cn === e.cn && c.geometry === e.geometry))
      out.push({ cn: e.cn, geometry: e.geometry });
  }
  return out;
}

/** Spin labels listed for an ion and coordination (null means the table does not distinguish spin). */
export function spins(el: string, ox: number, cn: number, geometry: Geometry | null = null): (Spin | null)[] {
  return SHANNON_ENTRIES.filter(
    (e) => e.el === el && e.ox === ox && e.cn === cn && e.geometry === geometry,
  ).map((e) => e.spin);
}

/**
 * Look up one radius. Returns `ok: false` with the entries that do exist instead of guessing:
 * no nearest coordination, no interpolation, no default spin when the table lists both.
 */
export function getRadius(q: RadiusQuery): RadiusResult {
  const ion = ionLabel(q.el, q.ox);
  const all = byElement(q.el);
  if (all.length === 0)
    return { ok: false, reason: 'unknown element', message: `No Shannon radii for ${q.el}.`, available: [] };
  const sameIon = all.filter((e) => e.ox === q.ox);
  const atCn = sameIon.filter((e) => e.cn === q.cn);
  const cn = coordinationLabel(q.cn);
  if (atCn.length === 0) {
    const listed = sameIon.length ? sameIon.map(describe).join(', ') : 'none';
    const msg = sameIon.length
      ? `${ion} has no entry for CN ${cn}. Listed for ${ion}: ${listed}.`
      : `${ion} is not in the table. Oxidation states listed for ${q.el}: ${oxidationStates(q.el).join(', ') || 'none'}.`;
    return { ok: false, reason: 'no entry', message: msg, available: sameIon.length ? sameIon : all };
  }
  const geometry = q.geometry ?? null;
  const notes: string[] = [];
  const geo = atCn.filter((e) => e.geometry === geometry);
  if (geo.length === 0) {
    if (geometry === null)
      return {
        ok: false,
        reason: 'geometry required',
        message: `${ion} at CN ${cn} is listed only as ${[...new Set(atCn.map((e) => GEOM_NAME[e.geometry!]))].join(' or ')}; choose the geometry.`,
        available: atCn,
      };
    return {
      ok: false,
      reason: 'no entry',
      message: `${ion} has no ${GEOM_NAME[geometry]} entry at CN ${cn}. Listed: ${atCn.map(describe).join(', ')}.`,
      available: atCn,
    };
  }
  const others = [...new Set(atCn.filter((e) => e.geometry !== geometry).map((e) => e.geometry!))];
  if (geometry === null && others.length)
    notes.push(
      `Plain CN ${cn} entry used; the table also lists ${others.map((g) => coordinationLabel(q.cn, g)).join(', ')}.`,
    );

  let pick: ShannonEntry | undefined;
  const labelled = geo.filter((e) => e.spin !== null);
  if (labelled.length === 0) {
    pick = geo[0];
    if (q.spin)
      notes.push(
        `The table does not distinguish spin for ${ion} at CN ${cn}; the ${q.spin} request does not change the value.`,
      );
  } else if (q.spin) {
    pick = geo.find((e) => e.spin === q.spin);
    if (!pick)
      return {
        ok: false,
        reason: 'no entry',
        message: `${ion} at CN ${cn} is listed only as ${labelled.map((e) => e.spin).join(', ')}, not ${q.spin}.`,
        available: geo,
      };
  } else if (labelled.length > 1) {
    return {
      ok: false,
      reason: 'spin required',
      message: `${ion} at CN ${cn} has both high-spin and low-spin radii; choose the spin state.`,
      available: geo,
    };
  } else {
    pick = labelled[0]!;
    notes.push(`Only the ${pick.spin} radius is listed for ${ion} at CN ${cn}; it was used.`);
  }
  const entry = pick!;
  const out: RadiusResult = { ok: true, value: entry[q.kind], entry };
  if (notes.length) out.note = notes.join(' ');
  return out;
}
